#!/usr/bin/env python3
"""Build the standalone LaLiga 2026/27 static mobile dashboard."""
from pathlib import Path
import csv,json
ROOT=Path(__file__).resolve().parent
with (ROOT/'laliga_2026_27_matches_official.csv').open(encoding='utf-8-sig',newline='') as f:
    matches=list(csv.DictReader(f))
with (ROOT/'laliga_2026_27_official_table_snapshot.csv').open(encoding='utf-8-sig',newline='') as f:
    official=list(csv.DictReader(f))
with (ROOT/'laliga_2026_27_official_zones.json').open(encoding='utf-8') as f:
    zone_data=json.load(f)
data={'matches':matches,'teams':sorted({m['home_team'] for m in matches}|{m['away_team'] for m in matches}),'officialTable':official,'zones':zone_data['zones']}
jsdata=json.dumps(data,ensure_ascii=False,separators=(',',':')).replace('</','<\\/')
